import {products} from './product-catalog.js';
import {readPhoto} from './photo-model.js';
import {createSizedModel} from './product-scale.js';
import {imageDifference,namedProductKey,capacityCompatible} from './product-match.js';
import {capacityLabel} from './product-specs.js';
import {generateProduct} from './modeling-client.js';
export async function identifyProduct(source,name=''){const photo=await readPhoto(source,35);for(const product of products){if(!capacityCompatible(product.size,name))continue;product.photos ||=product.references.map(ref=>readPhoto(ref,35).catch(()=>null));const refs=await Promise.all(product.photos);if(refs.some(ref=>ref&&imageDifference(photo,ref)<3))return {photo,product,matchedBy:'image'}}const key=namedProductKey(name),product=products.find(p=>p.key===key);return {photo,product:product||null,matchedBy:product?'name':null}}
export async function createDirectProduct(source,name,renderer,onProgress=()=>{},description=''){description=description.trim();if(!source||description){const photo=source?await readPhoto(source,35).catch(()=>({originalSource:source})):null;return generateProduct(photo?.originalSource||'',name,onProgress,null,description)}onProgress('正在识别产品与容量…');const {photo,product,matchedBy}=await identifyProduct(source,name);if(!product)return generateProduct(photo.originalSource,name,onProgress);onProgress('正在生成 '+product.size.name+' 的专属三维结构与材质…');const raw=await product.create(renderer);raw.position.y+=product.yOffset;const model=createSizedModel(raw,product.size);return {model,name:product.size.name+' · '+capacityLabel(product.size),kind:'已研究专属模型 · '+product.dossier.product,metadata:{photoSource:photo.originalSource,sourceFileName:name,photoConfig:{method:product.key,tolerance:35,physicalSize:structuredClone(model.userData.physicalSize)},photoResearch:product.dossier,photoMatchMethod:matchedBy}}}
